  roas: 1.5,
  posts_per_day: 3,
  support_emails: 16,
  support_resolved: 13,
  open_prs: 1
} }];

const j = $input.first().json;
const e = [];
if (!/^\d{4}-\d{2}-\d{2}$/.test(j.date||'')) e.push('date must be YYYY-MM-DD');
for (const k of ['downloads_7d','revenue_7d_usd','ad_spend_usd','roas','support_emails','support_resolved']) if (!Number.isFinite(j[k])) e.push(k + ' must be a number');
if (Number.isFinite(j.support_resolved) && Number.isFinite(j.support_emails) && j.support_resolved > j.support_emails) e.push('support_resolved cannot exceed support_emails');
if (e.length) throw new Error('Invalid metrics: ' + e.join('; '));
return [{ json: j }];

const raw = $json && $json.content && $json.content[0] && $json.content[0].text;
if (!raw || !raw.trim()) throw new Error('Anthropic returned empty brief');
const date = $('Validate Metrics').first().json.date;
return [{ json: { subject: 'Daily brief - ' + date, body: raw.trim() } }];

const sourceId="DaebyH0xIDQ";
const sourceUrl="https://www.instagram.com/chandlerintelligence/reel/DaebyH0xIDQ/";
const variant='USER_STACK';
const seen=new Set();
const hash=s=>{let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return (h>>>0).toString(16).padStart(8,'0');};
return $input.all().map(({json:j},i)=>{
  const recordKey=String(j.row_id||j.clip_id||j.note_id||j.fileName||j.output_path||j.title||i);
  const idempotencyKey=hash(sourceId+'|'+recordKey);
  if(seen.has(idempotencyKey)) throw new Error('Duplicate output in one execution: '+idempotencyKey);
  seen.add(idempotencyKey);
  return {json:{...j,source_provenance:{source_id:sourceId,source_url:sourceUrl,variant},idempotency_key:idempotencyKey,review_status:'needs_human_review',review_notes:Array.isArray(j.review_notes)?j.review_notes:[],external_actions_enabled:false}};
});
